const RELEASES=[{version:'__APP_VERSION__',title:"Gọn hơn: khung tùy chọn, hộp công việc, ô hôm nay",text:"Thu nhỏ khung Đồng bộ / Giao diện tối / Thông báo; hộp chi tiết công việc gọn và rõ hơn; sửa ô hôm nay của Việc hằng ngày bị lệch thấp hơn các ngày khác trên điện thoại và máy tính bảng.",tags:["giao diện","công việc","việc hằng ngày"],items:["Khung tùy chọn nhanh hẹp hơn, mỗi hàng thấp hơn nhưng nút vẫn bấm dễ","Hộp công việc: hàng tiêu đề một dòng, trạng thái lưu là viên nhỏ, mức độ xếp 2×2, bỏ dòng hướng dẫn lặp","Việc hằng ngày: vòng tròn hôm nay thẳng hàng với các ngày khác"]},{version:'1.64.0',title:"Kho câu: đủ 2.222 câu, thêm 110 lời Thiền sư Đường–Tống",text:"Thêm 110 lời của Mã Tổ, Bách Trượng, Nam Tuyền, Đại Châu Huệ Hải, Thạch Đầu, Dược Sơn, Động Sơn, Đức Sơn, Nham Đầu, Tuyết Phong, Vân Môn và Hoàng Bá. Tất cả đối chiếu nguyên văn Hán với Ngũ Đăng Hội Nguyên (CBETA). Kho câu đạt mục tiêu 2.222.",tags:["lời chào","kho câu","thiền sư"],items:["Bách Trượng 13, Mã Tổ 8, Thạch Đầu 9, Vân Môn 8, Dược Sơn 6, Động Sơn 5, Nam Tuyền 15, Đại Châu 18, Hoàng Bá 7, Đức Sơn 7, Nham Đầu 8, Tuyết Phong 6","Mỗi câu giữ nguyên văn Hán, bản dịch nghĩa tiếng Việt, tên sách và đường dẫn nguồn","Bản dịch tiếng Việt là bản dịch nghĩa, chưa thẩm định chuyên gia"]},{version:'1.63.0',title:"Kho câu: thêm 161 lời thiền sư xưa, lên 2.112 câu",text:"Thêm lời của Nhị tổ Huệ Khả, Lục tổ Huệ Năng, Tam tổ Tăng Xán, Bồ Đề Đạt Ma, Huyền Giác, Hoàng Bá, Lâm Tế, Vô Môn và vua Trần Nhân Tông. 155 câu được đối chiếu nguyên văn Hán với Đại Chính tạng; 6 câu Trần Nhân Tông ghi chú là tham khảo.",tags:["lời chào","kho câu","thiền sư"],items:["Huệ Năng 34, Huyền Giác 33, Tăng Xán 25, Hoàng Bá 19, Lâm Tế 19, Huệ Khả 16, Đạt Ma 8, Vô Môn 1, Trần Nhân Tông 6","Mỗi câu giữ nguyên văn Hán, bản dịch nghĩa tiếng Việt, tên kinh và đường dẫn nguồn","Bản dịch tiếng Việt là bản dịch nghĩa, chưa thẩm định chuyên gia"]},{version:'1.62.0',title:"Kho câu: thêm 374 câu từ nguồn công khai cho 11 tác giả, lên 1.951 câu",text:"Thêm 374 câu cho Lục tổ Huệ Năng, Hàn Sơn, Long Thọ, Plotinus, Rumi, Socrates, Krishnamurti, Hakuin, Adi Shankara, Phanxicô thành Assisi và Trần Nhân Tông. Phần lớn được đối chiếu nguyên văn với bản công khai; 4 câu Trần Nhân Tông ghi chú là tham khảo.",tags:["lời chào","kho câu","nguồn"],items:["Huệ Năng 100, Hàn Sơn 86, Long Thọ 66, Plotinus 30, Rumi 28, Socrates 22, Krishnamurti 11, Hakuin 10, Adi Shankara 9, Phanxicô 8, Trần Nhân Tông 4","Chỉ Huệ Năng đạt 100 câu mới; Liên Hoa Sinh, Milarepa và Đạo Nguyên chưa có câu mới","Bản dịch tiếng Việt là bản dịch nghĩa, chưa thẩm định chuyên gia"]},{version:'1.61.0',title:"Kho câu: thêm 51 câu tham khảo cho 11 tác giả mới, lên 1.577 câu",text:"Thêm 51 câu từ trang bên thứ ba có ghi nguồn cho Socrates, Plotinus, Meister Eckhart, Phanxicô thành Assisi, Hàn Sơn, Long Thọ, Huệ Năng, Ramana Maharshi, Krishnamurti, Trần Nhân Tông và vài tác giả khác. Tất cả được ghi chú là tham khảo.",tags:["lời chào","kho câu","tham khảo"],items:["Socrates 6, Krishnamurti 8, Meister Eckhart 6, Plotinus 6, Huệ Năng 6, Ramana Maharshi 6, Hàn Sơn 4, Phanxicô 3, Trần Nhân Tông 2, Long Thọ, Rumi, Deepak Chopra, Hakuin mỗi người 1", "Chưa đạt 100 câu cho mỗi tác giả: công cụ chỉ đọc được trích đoạn từ web, không tải được sách nguyên văn", "Chưa có câu mới cho Adi Shankara, Liên Hoa Sinh, Milarepa, Đạo Nguyên và Thích Nhất Hạnh", "Không đổi giao diện, logic chọn câu hay mục tiêu 2.222 câu"]},{version:'1.60.0',title:"Kho câu: thêm 166 câu có nguồn, lên 1.526 câu",text:"Thêm 166 câu có nguồn từ các tệp nguyên văn trong kho. Mỗi câu đối chiếu được với tệp nguồn; mục tiêu 2.222 câu không đổi.",tags:["lời chào", "kho câu", "nguồn"],items:["Trang Tử: thêm 100 câu từ bản dịch Giles của Nam Hoa Kinh", "Khổng Tử: thêm 20 câu Luận Ngữ, bản Legge", "Upanishad, Bhagavad Gita, Kabir, Mạnh Tử, Tuân Tử: thêm 46 câu", "Chưa đạt 100 câu cho mỗi tác giả: nguồn trong kho không đủ cho các tác giả còn lại; không thêm câu chưa đối chiếu được"]},{version:'1.59.1',title:'Ghi chú nguồn: câu chưa có nguồn chính thức là tham khảo',text:'Kho Osho giữ 111 câu có nguồn. Các câu đối chiếu trên trang bên thứ ba và câu Dōgen được ghi chú là tham khảo.',tags:['lời chào','Osho','nguồn'],items:['Đánh dấu tham khảo cho 20 câu Osho đối chiếu trên quotewise.io hoặc thư viện Overdrive, chưa có nguồn chính thức','Đánh dấu tham khảo cho câu Dōgen, chưa có nguồn xác thực; giữ nguyên theo yêu cầu','Gợi ý chiêm nghiệm ghi rõ là không phải lời trích','Không đổi nội dung câu, bản dịch, liên kết hay thứ tự ưu tiên']},{version:'1.59.0',title:'Kho Osho: thêm 78 câu có nguyên văn, lên 111 câu',text:'Kho Osho có 111 câu có nguồn, thêm 78 câu có nguyên văn tiếng Anh hiển thị trên oshonews.com. Mỗi câu có liên kết tới trang gốc. Gợi ý chiêm nghiệm và câu Dōgen giữ nguyên.',tags:['lời chào','Osho','nguồn'],items:['Thêm 78 câu Osho có nguyên văn tiếng Anh, đưa kho Osho lên 111 câu có nguồn','Mỗi câu có liên kết tới bài gốc trên oshonews.com và bản dịch tiếng Việt khớp với câu gốc','Đối chiếu qua trang chuyên mục và thẻ của oshonews.com; chưa mở được từng bài gốc trong lần này','Gợi ý chiêm nghiệm và câu Dōgen giữ nguyên theo yêu cầu','Thứ tự ưu tiên Osho giữ nguyên']},{version:'1.58.0',title:'Kho Osho: chỉ giữ câu có nguyên văn đã kiểm chứng',text:'Gỡ 79 câu Osho chưa tìm được nguyên văn tiếng Anh. Kho còn 33 câu Osho có nguồn đã đối chiếu, cộng một gợi ý chiêm nghiệm không phải lời trích.',tags:['lời chào','Osho','nguồn'],items:['Gỡ 79 câu Osho chưa tìm được nguyên văn tiếng Anh trên trang trích dẫn hoặc oshonews.com','Giữ 26 câu cũ có nguyên văn; sửa bản dịch cho khớp, nhiều câu chỉ giữ phần đã kiểm chứng','Kho còn 33 câu Osho có nguồn đã đối chiếu, cộng 1 gợi ý chiêm nghiệm được ghi rõ là không phải lời trích','Đối chiếu qua trang trích dẫn bên thứ ba và oshonews.com; chưa đối chiếu bản in của sách','Thứ tự ưu tiên Osho giữ nguyên']},{version:'1.57.0',title:'Kho Osho: bỏ câu chưa kiểm chứng, thêm 7 câu có nguồn',text:'Bỏ 6 câu Osho chưa kiểm chứng được nguồn, thêm 7 câu Osho có nguồn đã đối chiếu trên oshonews.com. Kho có 112 câu Osho; phần còn lại vẫn là bản dịch nghĩa, chưa đối chiếu nguyên văn.',tags:['lời chào','Osho','nguồn'],items:['Bỏ 6 câu Osho biên soạn chưa có nguồn đã kiểm chứng','Thêm 7 câu Osho có nguyên văn trên oshonews.com, ghi rõ sách và chương','Kho có 112 câu Osho; 105 câu cũ vẫn ghi là bản dịch nghĩa, chưa đối chiếu nguyên văn','Ưu tiên hiển thị Osho ở nửa đầu chu kỳ giữ nguyên']},{version:'1.56.0',title:'Gom tùy chọn nhanh vào một dropdown, đưa tìm kiếm về giữa',text:'Đồng bộ, giao diện tối và thông báo gom vào một nút Tùy chọn nhanh có biểu tượng nhận biết. Ô tìm kiếm nằm giữa thanh công cụ ở mọi kích thước màn hình.',tags:['thanh công cụ','dropdown','tìm kiếm','giao diện'],items:['Đồng bộ, giao diện tối và thông báo gom vào dropdown Tùy chọn nhanh','Chấm đỏ trên nút khi có thông báo cần xem','Ô tìm kiếm căn giữa thanh công cụ ở 390, 820 và 1440 px','Mở và đóng bằng bấm, phím Escape hoặc bấm ra ngoài']},{version:'1.55.2',title:'Ô thêm việc mới gọn hơn trong checklist',text:'Ô nhập việc mới hiển thị trên một dòng, placeholder ngắn gọn, nút Thêm căn giữa và gợi ý rút gọn để không xuống dòng trên điện thoại.',tags:['checklist','giao diện','responsive'],items:['Placeholder rút gọn: Thêm việc cần làm…','Ô nhập và nút Thêm cùng một dòng, căn giữa theo chiều dọc','Gợi ý phím tắt rút gọn, không còn xuống dòng trên 390 px']},{version:'1.55.1',title:'Căn lề checklist theo một trục, sửa lỗi kiểm tra vùng chạm',text:'Tay kéo, ô tick và nút × nay căn thẳng hàng với dòng chữ đầu của mỗi mục. Vùng chạm cảm ứng đủ 44px, ô nội dung rộng hơn trên điện thoại. Bản này gom các thay đổi 1.53.0 đến 1.55.0, vốn chưa được phát hành do bài kiểm tra CI không đạt.',tags:['checklist','căn lề','responsive','cảm ứng'],items:['Tay kéo, ô tick và nút × căn giữa theo dòng chữ đầu tiên của mục','Lưới 4 cột cố định, ô nội dung rộng hơn trên điện thoại','Vùng chạm 44px cho tay kéo và nút × khi dùng cảm ứng; chuột dùng kích thước gọn hơn','Nhật ký phiên bản 1.53.0 đến 1.55.0 có đủ ghi chú và từ khóa']},{version:'1.55.0',title:'Căn lề checklist theo một trục',text:'Tay kéo, ô tick và nút × cùng căn theo dòng chữ đầu; lưới 4 cột thay cho các lưới chồng nhau cũ. Bản phát hành này chưa được triển khai do kiểm tra vùng chạm cảm ứng chưa đạt, được sửa ở 1.55.1.',tags:['checklist','căn lề'],items:['Căn giữa tay kéo, ô tick và nút × với dòng chữ đầu','Xóa các quy tắc lưới chồng nhau và khối cảm ứng gây lệch','Giảm số khai báo !important từ 832 xuống 829']},{version:'1.54.0',title:'Hoàn thành 111 câu nói Osho',text:'Kho lời chào có đủ 111 câu Osho Việt hóa. Bản này chưa được triển khai do bài kiểm tra nhật ký phiên bản chưa đạt, được sửa ở 1.55.1.',tags:['lời chào','Osho','nguồn'],items:['Thêm 6 câu Osho Việt hóa, tổng 111 câu trong kho','Kho có 1.360 trích đoạn có nguồn']},{version:'1.53.0',title:'Sửa lỗi lệch khung checklist',text:'Lần sửa đầu tiên cho lỗi lệch khung checklist. Chưa triệt để và được thay thế bởi 1.55.0.',tags:['checklist'],items:['Khôi phục khoảng cách trên của ô tick so với nội dung','Bỏ một phần quy tắc lưới chồng nhau']},{version:'1.52.0',title:'Mở rộng Quỷ Cốc Tử lên 30 câu, thêm ~100 câu Osho',text:'Kho lời chào có thêm 16 câu Quỷ Cốc Tử (tổng 30 câu có nguồn) và ~97 câu triết học tỉnh thức từ Osho, Việt hóa toàn bộ. Osho ưu tiên hiển thị nhiều hơn trong vòng xoay.',tags:['lời chào','Quỷ Cốc Tử','Osho','nguồn','tỉnh thức'],items:['Mở rộng Quỷ Cốc Tử từ 14 lên 30 câu có nguồn từ tệp nguồn tiếng Việt','Thêm ~97 câu Osho Việt hóa hoàn toàn vào kho lời chào','Osho được ưu tiên hiển thị trước trong chu kỳ xoay vòng','Lời chào vẫn xoay vòng, không lặp trong một chu kỳ']},{version:'1.51.0',title:'Thêm 14 câu Quỷ Cốc Tử vào kho lời chào',text:'Kho lời chào có thêm 14 câu ngắn từ Quỷ Cốc Tử, bản dịch tiếng Việt của Nguyễn Lư. Mỗi câu ghi rõ điều và chương trong sách.',tags:['lời chào','Quỷ Cốc Tử','nguồn'],items:['Thêm 14 trích đoạn có nguồn từ Quỷ Cốc Tử, đối chiếu với tệp nguồn trước khi nạp','Mỗi câu ghi rõ điều và chương trong sách','Lời chào vẫn xoay vòng, không lặp trong một chu kỳ']},{version:'1.50.1',title:'Khung ô hôm nay không còn đè lên ngày bên cạnh',text:'Khung đánh dấu ngày hôm nay trong việc hằng ngày chỉ cao thêm, đúng bề rộng cột, không chồng lên vòng tròn của ngày kế bên.',tags:['việc hằng ngày','khung hôm nay','canh lề','giao diện'],items:['Khung ô hôm nay đúng bề rộng cột, không đè lên vòng tròn T2 hoặc T4','Khung vẫn bao trọn nhãn ngày và vòng tròn của hôm nay','Không đổi dữ liệu hay cách đánh dấu việc']},{version:'1.50.0',title:'Checklist gọn, không còn %; thanh trên gom một chỗ',text:'Checklist chỉ hiện nội dung và số mục đã xong. Thanh trên có một cụm nút bên phải và ô tìm kiếm ở giữa.',tags:['checklist','phần trăm','thanh trên','tìm kiếm','giao diện'],items:['Bỏ ô % và chữ % ở từng mục checklist; nội dung chiếm trọn dòng','Bỏ con số % trong tiêu đề tiến độ checklist, giữ số mục đã xong (ví dụ 2/5 mục đã hoàn thành)','Thanh trên: ô tìm kiếm ở giữa; trạng thái lưu, sáng/tối, chuông và avatar gom một cụm bên phải','Trên điện thoại: nút ☰, tìm kiếm và cụm nút nằm trên một hàng']},{version:'1.49.0',title:'Dán nhiều dòng vào ghi chú không còn chồng dòng',text:'Dán hoặc gõ nhiều dòng vào card ghi chú giờ hiện đủ từng dòng, không còn chồng lên nhau.',tags:['ghi chú','dán','xuống dòng','giao diện'],items:['Dán nhiều dòng vào card ghi chú không còn chồng dòng','Gõ nhiều dòng trong ghi chú cũng hiển thị rõ từng dòng','Dòng trống khi dán giữ khoảng cách gọn như cũ']},{version:'1.48.0',title:'Đường nối Gantt mềm mại, kéo để đổi đường đi',text:'Đường nối giữa các công việc trên Gantt đi theo góc bo tròn; kéo tay nắm giữa đường để đổi đường đi theo ý bạn.',tags:['gantt','đường nối','mũi tên','kéo thả','giao diện'],items:['Đường nối mềm mại hơn, đi theo góc bo tròn thay cho đường cong cũ','Kéo tay nắm giữa đường nối để đổi đường đi; dùng được bằng chuột, ngón tay hoặc phím mũi tên','Vị trí đường đi giữ nguyên khi đổi khoảng xem 7, 15 hoặc 30 ngày']},{version:'1.47.1',title:'Tên tab dự án dài hiện đủ, không bị cắt',text:'Tên dự án dài trên dải tab xuống dòng và canh giữa trong khung; khung giữ nguyên chiều rộng và chỉ cao thêm khi cần đủ dòng.',tags:['tab dự án','tràn chữ','xuống dòng','canh giữa','giao diện'],items:['Tên dự án dài xuống dòng trong khung tab, không bị cắt chữ','Khung tab giữ nguyên chiều rộng, viền và bo góc','Phần trăm tiến độ luôn nằm một dòng cuối tab','Khi tab cao thêm, ô đang lấy nét không bị khung dính che khi cuộn']},{version:'1.46.0',title:'Việc đã xong tự gỡ khỏi khu ghim',text:'Khi một việc đã hoàn thành, việc đó tự được gỡ ghim khỏi mục "Ghim công việc" ở thanh bên. Thanh bên chỉ còn việc đang mở, gọn và ít rối mắt hơn.',tags:['ghim','thanh bên','hoàn thành','gọn','việc đang mở'],items:['Việc đã ở cột Xong sẽ tự bỏ ghim khi lưu','Việc vừa hoàn thành rời khỏi khu ghim ngay','Việc đang mở vẫn giữ ghim; ghim và bỏ ghim thủ công vẫn dùng được']},{version:'1.45.0',title:'Lời chúc lớn khi gỡ hết việc quá hạn hoặc hoàn tất dự án',text:'Khi việc quá hạn cuối cùng được xong, hoặc mọi việc của một dự án đã hoàn tất, lời chúc hiện khung rộng có icon và họa tiết.',tags:['chúc mừng','hoàn thành','quá hạn','dự án','lời chúc','icon'],items:['Gỡ hết việc quá hạn: hiện lời chúc riêng, khung rộng hơn','Hoàn tất mọi việc của một dự án: lời chúc riêng cho dự án','Có 30 lời chúc mới, mỗi lần một câu khác','Nút đóng đủ lớn để chạm trên điện thoại']},{version:'1.44.0',title:'Chữ gõ không bị đổi định dạng khi mở lại',text:'Các ký tự như *, __, #, dấu gạch đầu dòng hay số kèm dấu chấm được giữ nguyên là chữ thường trong mô tả việc, dự án và ghi chú.',tags:['định dạng','ghi chú','mô tả','soạn thảo','ký tự','lỗi'],items:['Gõ "5 * 3 * 2" không còn bị in nghiêng khi mở lại','Gõ "__tên__" hoặc "# tiêu đề" như chữ thường không bị gạch chân hay thành tiêu đề','In đậm kèm khoảng trắng ở cuối vẫn giữ đúng định dạng']},{version:'1.43.0',title:'Chọn giờ nhắc việc hằng ngày dễ hơn',text:'Giờ nhắc có nút gợi ý nhanh và hai ô giờ, phút thay cho ô giờ của trình duyệt.',tags:['nhắc lúc','giờ nhắc','việc hằng ngày','chọn giờ','không nhắc'],items:['Nút gợi ý nhanh: 7:00, 12:00, 18:00, 21:00','Chọn giờ và phút bằng hai ô, phút theo bước 5','Nút "Không nhắc" xóa giờ nhắc của việc','Dòng trạng thái cho biết việc sẽ được nhắc lúc mấy giờ']},{version:'1.42.0',title:'Ô % gọn ngay cuối dòng checklist',text:'Bỏ thanh kéo tiến độ cho gọn. Mỗi mục giờ gồm ô đánh dấu, nội dung và số % in đậm cuối dòng; gõ số trực tiếp.',tags:['checklist','phần trăm','tiến độ','ô số','gọn','mục'],items:['Thanh kéo tiến độ được thay bằng ô số nhỏ cuối mỗi dòng checklist','Gõ số từ 0 đến 100; số lớn hơn 100 tự về 100','Tick mục đưa về 100%, bỏ tick đưa về 0%','Chế độ tập trung dùng cùng ô số']},{version:'1.41.0',title:'Lời nhắc nhẹ khi hôm nay chưa có việc nào được tích',text:'Một dòng gợi ý nhẹ mở đầu ngày. Hiện ở tuần hiện tại, đóng một lần là thôi đến hết ngày.',tags:['nhắc việc','lời nhắc','chưa tích','hôm nay','việc hằng ngày','gợi ý'],items:['Hiện lời nhắc nhẹ khi hôm nay chưa tích việc nào, ở tuần hiện tại','Bấm Đóng thì ẩn đến hết ngày; tích một việc thì ẩn ngay','Không hiện khi mọi việc đều nghỉ hôm nay']},{version:'1.40.0',title:'Báo cáo riêng cho từng việc hằng ngày',text:'Xem lịch sử của một việc với tỷ lệ, chuỗi dài nhất và ghi chú trong 28 hoặc 90 ngày.',tags:['lịch sử','báo cáo','xem lịch sử','tỷ lệ','chuỗi','việc hằng ngày'],items:['Nút Xem lịch sử bằng chữ ở dòng cuối của từng việc, thay biểu tượng cũ','Báo cáo riêng của việc: chọn xem 28 hoặc 90 ngày','Hiện tỷ lệ hoàn thành (không tính ngày nghỉ) và chuỗi dài nhất trong khoảng đã chọn','Ghi chú cảm nhận hiện trong báo cáo']},{version:'1.39.0',title:'Kéo để đổi thứ tự việc hằng ngày',text:'Sắp xếp việc quan trọng lên đầu bằng cách kéo tay cầm. Thứ tự được đồng bộ giữa các thiết bị.',tags:['đổi thứ tự','kéo thả','việc hằng ngày','tay cầm','sắp xếp','thứ tự'],items:['Kéo tay cầm (sáu chấm) để đổi thứ tự việc hằng ngày, bằng chuột hoặc cảm ứng','Trên bàn phím: chọn tay cầm rồi nhấn mũi tên lên hoặc xuống','Thứ tự được lưu và đồng bộ giữa các thiết bị']},{version:'1.38.0',title:'Ghi chú cảm nhận theo từng ngày',text:'Giữ một ô ngày để ghi lại cảm nhận ngay tại chỗ. Ghi chú được đồng bộ giữa các thiết bị.',tags:['ghi chú','ghi chú cảm nhận','giữ ô','chuột phải','Shift+Enter','lịch sử'],items:['Giữ một ô ngày (0,5 giây) để ghi chú cảm nhận cho ngày đó; trên máy tính: chuột phải hoặc Shift+Enter','Ô đã có ghi chú hiện chấm tím; lịch sử 28 ngày liệt kê ghi chú','Để trống rồi lưu để xóa ghi chú; tối đa 140 ký tự']},{version:'1.37.0',title:'Sửa tràn ngang khi tích việc hằng ngày trên máy tính bảng',text:'Việc hằng ngày không còn tràn ngang ở 820 px khi tích việc. Không đổi dữ liệu hay chức năng.',tags:['việc hằng ngày','máy tính bảng','820','bố cục','tràn ngang','tiến độ'],items:['Việc hằng ngày không còn tràn ngang trên máy tính bảng 820 px khi tích việc','Phần trăm tiến độ tuần được xuống dòng thay vì bị đẩy ra ngoài màn hình','Thêm kiểm thử ở 390, 820 và 1440 px cho trường hợp này']},{version:'1.36.0',title:'Thanh chuyển chế độ không còn lộ nội dung khi cuộn',text:'Trên điện thoại, thanh Bảng Kanban, Lịch, Gantt khi cuộn có nền đặc, không còn để lộ tên việc và các ô tròn bên dưới.',tags:['Việc hằng ngày','Bố cục điện thoại'],items:['Thanh chuyển chế độ (Bảng Kanban, Lịch, Gantt) dính trên đầu khi cuộn trên điện thoại giờ có nền đặc.','Trước đây nền thanh trong suốt 3%, nên tên việc và các ô tròn bên dưới lộ qua khi cuộn.','Áp dụng cho cả chế độ sáng và chế độ tối.']},{version:'1.35.0',title:'Sửa nút Làm mới (đồng bộ) ở Chế độ tập trung',text:'Nút Làm mới ở Chế độ tập trung hiển thị đúng trên điện thoại: biểu tượng và chữ nằm gọn trong nút, không còn lệch hay tràn.',tags:['Đồng bộ','Chế độ tập trung'],items:['Nút “Làm mới” ở Chế độ tập trung (kiểm tra dữ liệu mới từ máy chủ) hiển thị đúng trên điện thoại: biểu tượng và chữ nằm gọn trong nút.','Trước đây nút bị ép thành ô vuông 44 px: chữ “Làm mới” tràn ra ngoài và biểu tượng lệch khỏi nền tím.','Nguyên nhân: hai bộ quy tắc CSS của hai thời điểm thiết kế đè lên nhau. Đã bỏ quy tắc cũ, giữ kiểu có nhãn chữ cho mọi trang.','Nút không còn đổi sang nền trắng khi rê chuột, nên chữ luôn đọc được.','Bấm nút vẫn hoạt động như cũ: tải dữ liệu mới nhất, hoặc báo lý do chưa làm mới được.']},{version:'1.34.0',title:'Giờ nhắc riêng cho từng việc hằng ngày',text:'Mỗi việc hằng ngày giờ có thể đặt giờ nhắc riêng. Đến giờ và chưa làm, việc sẽ hiện ở đầu trang Việc hằng ngày và trong chuông thông báo.',tags:['Việc hằng ngày','Nhắc việc'],items:['Nhắc lúc: ô giờ (theo đồng hồ 24 giờ) trong biểu mẫu Thêm hoặc Sửa việc hằng ngày. Để trống thì việc đó không được nhắc.','Giờ nhắc tính theo giờ Việt Nam, cùng múi giờ với ngày trong ứng dụng.','Khi đến giờ nhắc, việc chưa làm và chưa nghỉ hôm nay hiện trong khung “đến giờ nhắc” ở đầu trang Việc hằng ngày, kèm nút “Đã xem”.','Việc đã làm hoặc đã đánh dấu nghỉ hôm nay không được nhắc.','Mỗi dòng việc có dấu “Nhắc 07:30” để thấy giờ nhắc ngay.','Chuông thông báo hiện chấm và nêu tên việc đến giờ nhắc. Số việc quá hạn trên chuông không đổi, vì nhắc việc không tính là việc quá hạn.','Bấm một mục trong hộp thoại Thông báo để mở đúng trang Việc hằng ngày.','“Đã xem” tắt nhắc của việc đó đến hết ngày, hoặc đến khi đổi giờ nhắc. Trạng thái này lưu trên trình duyệt đang dùng.','Trang tự hiện khung nhắc khi đến giờ, không cần tải lại; không tự cập nhật khi đang mở biểu mẫu.','Dữ liệu: thêm trường giờ nhắc (không bắt buộc, dạng HH:MM) cho từng việc. Việc cũ không có trường này vẫn hoạt động như trước; đồng bộ theo từng việc như các trường khác.','Máy chủ chỉ nhận giờ đúng dạng HH:MM và từ chối giờ sai, ví dụ 7:30, 25:00 hoặc 07:60.']},{version:'1.33.0',title:'Nghỉ hôm nay và lịch sử từng việc',text:'Ngày nghỉ không làm đứt chuỗi; mỗi việc có lịch sử 28 ngày gần nhất ngay trên thẻ.',tags:['Việc hằng ngày','Tính năng'],items:['Nghỉ hôm nay: đánh dấu ngày nghỉ khi chưa làm việc đó; ngày nghỉ không làm đứt chuỗi và không được tính là đã làm.','Lịch sử: nút trên từng việc mở 28 ngày gần nhất (đã làm, nghỉ, chưa làm) và chuỗi hiện tại.','Máy chủ và ứng dụng chấp nhận trường nghỉ mới (tùy chọn; dữ liệu cũ không đổi).']},{version:'1.32.0',title:'Việc hằng ngày gọn và dễ bấm trên điện thoại',text:'Nút Lưu luôn nhìn thấy, tên việc gọn, biểu tượng dễ chọn trên điện thoại; ghi chú tiến độ rõ hơn.',tags:['Việc hằng ngày','Giao diện'],items:['Nút Lưu và Hủy luôn nhìn thấy ở cuối hộp thoại trên điện thoại.','Tên việc dài tối đa 2 dòng; biểu tượng xếp 4 cột trên điện thoại.','Ghi chú tiến độ gọn hơn: Còn X lượt cần làm · đã làm Y/Z.','Bỏ dòng tiêu đề lặp; nhãn Chưa gắn dự án nhạt hơn.']},{version:'1.31.0',title:'Nhật ký phiên bản rõ từng bản',text:'Mỗi phiên bản là một khung riêng, có từ khóa hạng mục đã cải thiện và nội dung chi tiết hơn.',tags:['Giao diện','Nhật ký'],items:['Nhật ký phiên bản: mỗi phiên bản là một khung riêng.','Mỗi khung có từ khóa cho biết hạng mục đã cải thiện (ví dụ Đồng bộ, Bảo mật).','Chi tiết hơn cho các bản 1.25.0 đến 1.30.0.','Gỡ thẻ tóm tắt cứng trên Tổng quan đang hiển thị sai nội dung.']},{version:'1.30.0',title:'Bỏ nút đăng xuất mọi thiết bị',text:'Phần Phiên đăng nhập trong Cài đặt không còn nút Đăng xuất mọi thiết bị. Nút Đăng xuất của máy này vẫn giữ nguyên.',tags:['Bảo mật','Đăng nhập'],items:['Bỏ nút "Đăng xuất mọi thiết bị" trong Cài đặt.','Nút "Đăng xuất" của máy này giữ nguyên.','Máy chủ và dữ liệu không đổi.']},{version:'1.29.0',title:'Kiểm chứng đồng bộ khi hai thiết bị cùng sửa',text:'Đã kiểm tra cách gộp khi hai thiết bị cùng sửa: thay đổi khác mục được gộp tự động, thay đổi cùng trường không bị ghi đè âm thầm. Thêm kiểm thử cho việc này.',tags:['Đồng bộ','Kiểm thử'],items:['Thêm kiểm thử: hai thiết bị cùng sửa, thay đổi khác mục được gộp tự động.','Thay đổi cùng một trường không bị ghi đè âm thầm.','Không đổi logic đồng bộ; danh sách xung đột theo từng mục chưa làm vì chưa có số liệu.']},{version:'1.28.0',title:'Liên kết chia sẻ bảng không còn lộ token',text:'Liên kết chia sẻ mới đưa token ra sau dấu #, nên không đi qua máy chủ và không vào nhật ký truy cập. Liên kết cũ vẫn mở được.',tags:['Chia sẻ','Bảo mật'],items:['Liên kết chia sẻ bảng đưa token ra sau dấu #, không gửi lên máy chủ.','Trang xóa token khỏi thanh địa chỉ sau khi mở.','Liên kết cũ ?boardshare= vẫn mở được.','Thu hồi và hạn 7 ngày giữ nguyên.']},{version:'1.27.0',title:'Nâng mức bảo vệ mật khẩu khi đăng nhập',text:'Mật khẩu mới được mã hóa mạnh hơn. Tài khoản cũ được nâng cấp tự động ở lần đăng nhập đúng kế tiếp. Không cần đổi mật khẩu.',tags:['Bảo mật','Đăng nhập'],items:['Mật khẩu mới băm 600.000 vòng (trước là 100.000).','Tài khoản cũ được nâng cấp tự động ở lần đăng nhập đúng kế tiếp.','Không cần thao tác và không đổi dữ liệu công việc.']},{version:'1.26.0',title:'Đăng xuất dọn bản sao dữ liệu trên thiết bị',text:'Khi đăng xuất và đã đồng bộ hết, dữ liệu tài khoản được xóa khỏi bộ nhớ trình duyệt trên thiết bị này. Nếu còn thay đổi chưa gửi, hệ thống chặn đăng xuất và giữ lại dữ liệu.',tags:['Đăng nhập','Bảo mật','Đồng bộ'],items:['Đăng xuất xóa bản sao dữ liệu tài khoản trên trình duyệt khi đã đồng bộ hết.','Nếu còn thay đổi chưa gửi, đăng xuất bị từ chối để không mất dữ liệu.','Khóa tự động cũng dọn khi không còn thay đổi chưa gửi.']},{version:'1.25.0',title:'Menu bên trái chia nhóm, mục ít dùng nằm trong Thêm',text:'Menu chia nhóm Làm việc và Ý tưởng. Lưu trữ và Thùng rác nằm trong mục Thêm thu gọn. Các mục vẫn đầy đủ, không đổi cách mở.',tags:['Điều hướng','Giao diện'],items:['Menu chia nhóm Làm việc và Ý tưởng.','Lưu trữ và Thùng rác gom vào mục Thêm thu gọn.','Các màn hình giữ nguyên, chỉ đổi cách sắp xếp menu.']},{version:'1.24.0',title:'Đăng nhập máy dùng chung và tuần mới rõ hơn',text:'Việc hằng ngày: trên điện thoại mỗi ô có số ngày và chấm hôm nay; ghi chú tiến độ cho biết còn bao nhiêu lượt. Đăng nhập có lựa chọn Máy cá nhân. Cài đặt có Đăng xuất mọi thiết bị.',tags:['Đăng nhập','Việc hằng ngày']},{version:'1.23.0',title:'Việc hằng ngày: nhận biết hôm nay và chọn biểu tượng dễ hơn',text:'Đầu bảng và chip báo đúng thứ, ngày hôm nay. Biểu mẫu căn lề đều, chọn biểu tượng có thư viện tìm kiếm như form dự án.',tags:['Việc hằng ngày','Giao diện']},{version:'1.22.1',title:'Đăng nhập nhớ tài khoản, không phải nhập lại',text:'Email đã dùng được nhớ trên thiết bị và ghi nhớ thiết bị mặc định được tích, nên không bị đăng xuất sau 10 phút.',tags:['Đăng nhập']},{version:'1.22.0',title:'Việc hằng ngày gắn dự án và mục tiêu theo tuần',text:'Mỗi việc chọn được số lần trong tuần (1–7) và dự án liên quan. Tiến độ cộng gộp theo mục tiêu; mọi ngày, kể cả T7 và CN, đều tích được.',tags:['Việc hằng ngày','Dự án']},{version:'1.21.1',title:'Giao diện trong Cài đặt dễ chọn hơn',text:'Phần Giao diện trong Cài đặt đổi sang danh sách có icon, mô tả ngắn và dấu tích ở lựa chọn đang dùng. Bấm cả dòng để chọn, vẫn dùng được bàn phím.',tags:['Giao diện']},{version:'1.21.0',title:'Báo cáo Việc hằng ngày',text:'Việc hằng ngày có thanh tiến độ cộng gộp, trạng thái hoàn thành hôm nay rõ ràng và nút Báo cáo với biểu đồ, đánh giá, đề xuất cải thiện. Biểu mẫu thêm việc gọn hơn, không tràn viền.',tags:['Báo cáo','Việc hằng ngày']},{version:'1.20.1',title:'Sửa đồng bộ Việc hằng ngày',text:'Sửa lỗi Việc hằng ngày không đồng bộ lên máy chủ (báo Chưa đồng bộ được). Dữ liệu trên thiết bị vẫn còn và sẽ tự đồng bộ.',tags:['Đồng bộ','Việc hằng ngày']},{version:'1.20.0',title:'Việc hằng ngày',text:'Thêm mục Việc hằng ngày dưới Tất cả công việc: bảng thói quen theo tuần với dấu tích có hiệu ứng nhẹ, màu riêng cho từng việc, chuỗi ngày liên tiếp, thêm, sửa và xóa.',tags:['Việc hằng ngày']},{version:'1.19.15',title:'Menu điện thoại gọn hơn',text:'Menu trên điện thoại bỏ mục Dự án và hiện khung 3 chế độ xem (Bảng Kanban, Lịch, Gantt) để chuyển ngay trong menu.',tags:['Điều hướng','Giao diện']},{version:'1.19.14',title:'Bấm × không báo chưa lưu sai',text:'Mở một việc có checklist rồi bấm × không còn hiện bảng "Bạn có thay đổi chưa lưu" khi thực tế chưa sửa gì. Sửa thật vẫn được nhắc như trước.',tags:['Thông báo','Đồng bộ']},{version:'1.19.13',title:'Nút thoát đồng bộ',text:'Mọi nút × thoát trên website nay cùng một kiểu với nút của hộp công việc: 44×44, cùng màu và bo góc. Bảng lệnh (Ctrl+K) đổi chữ "Đóng" thành nút ×.',tags:['Đồng bộ']},{version:'1.19.12',title:'Ghim công việc ngay trong hộp chi tiết',text:'Nút Ghim đặt cạnh nút Chế độ tập trung trong hàng tiêu đề của hộp công việc. Bấm để ghim hoặc bỏ ghim; việc đã ghim hiện ở menu bên trái.',tags:['Ghim','Công việc']},{version:'1.19.11',title:'Ô thêm checklist cân đối',text:'Nút "+ Thêm" và ô nhập trong ô "Thêm mục mới" của checklist nay căn giữa đều trên dưới, không còn lệch xuống dưới.',tags:['Checklist','Giao diện']},{version:'1.19.10',title:'Checklist không còn tràn viền',text:'Nút kéo ⠿ và vòng focus của dòng checklist nằm gọn trong dòng, không ló ra ngoài góc bo hay đè lên ô tick (nhất là trên điện thoại).',tags:['Checklist','Giao diện']},{version:'1.19.9',title:'Bảng thoát hiện đúng nơi đang đọc và có nút Lưu',text:'Khi thoát hộp công việc còn thay đổi chưa lưu, bảng xác nhận hiện ngay trong khung nhìn đang đọc và có nút Lưu.',tags:['Giao diện']},{version:'1.19.8',title:'Sửa tranh giành con trỏ khi vẽ lại checklist',text:'Chế độ tập trung: vẽ lại checklist sau Xóa/Hoàn tác không còn giật con trỏ khỏi ô bạn vừa chuyển tới.',tags:['Checklist','Sửa lỗi']},{version:'1.19.7',title:'Khung Chế độ xem bo tròn, thanh tiến độ checklist mỏng hơn',text:'Khung Chế độ xem ở thanh bên bo tròn; thanh tiến độ từng mục checklist mỏng hơn, đầu tô luôn bo tròn khi kéo.',tags:['Giao diện','Checklist']},{version:'1.19.6',title:'Gantt ẩn công việc đã hoàn thành',text:'Chế độ Gantt chỉ hiện việc chưa xong; việc ở cột Hoàn thành được ẩn khỏi biểu đồ.',tags:['Gantt','Công việc']},{version:'1.19.5',title:'Sửa nút Tải lại trang đè lên nút Xem chi tiết',text:'Thông báo có bản mới hiện hai nút xếp cạnh nhau, không còn chồng lên nhau.',tags:['Giao diện','Sửa lỗi']},{version:'1.19.4',title:'Checklist gọn và bo tròn hơn',text:'Mỗi dòng checklist gọn hơn, thanh tiến độ bo tròn; khung Thêm mục mới là một ô bo tròn có nút Thêm bên trong, gợi ý nằm dưới khung.',tags:['Checklist','Giao diện']},{version:'1.19.3',title:'Ghim công việc trở lại',text:'Thẻ công việc có lại nút ghim. Thanh bên có mục Ghim công việc nằm trên Ghi chú ghim nhanh: hiện tối đa 3 việc, có nút xem tất cả và bỏ ghim nhanh.',tags:['Ghim']},{version:'1.19.2',title:'Kho lời chào thêm 200 câu từ kinh điển Ấn Độ',text:'Thêm 200 trích đoạn có nguồn đối chiếu từ Upanishad, thơ Kabir và Bhagavad Gita. Kho hiện có 1.220 câu có nguồn trên mục tiêu 2.222; phần còn lại sẽ bổ sung dần theo từng bản.',tags:['Lời chào']},{version:'1.19.1',title:'Lời chào tự bật đúng 4 buổi trong ngày',text:'Lời chào Chào mừng bạn trở lại tự bật đúng lúc ở 4 buổi sáng, trưa, chiều, tối (giờ Việt Nam), mỗi buổi một câu khác nhau, kể cả khi mở tab ngầm, máy chủ chậm hoặc mạng chập chờn.',tags:['Lời chào']},{version:'1.19.0',title:'Checklist gọn hơn, có thanh tiến độ',text:'Bỏ nút lên xuống trong checklist, chỉ còn kéo thả. Mỗi mục có thanh tiến độ % tự chỉnh; tick là 100%. Tiến độ việc là trung bình các mục, tiến độ dự án là trung bình các việc.',tags:['Checklist']},{version:'1.18.4',title:'Bỏ ghim trên thẻ công việc',text:'Thẻ công việc ở bảng Kanban không còn nút ghim. Việc đã ghim trước đó vẫn hiện ở mục Pin bên trái và vẫn bỏ ghim được.',tags:['Ghim','Công việc']},{version:'1.18.3',title:'Cài đặt gọn hơn',text:'Phần Giao diện và Dung lượng dữ liệu trong Cài đặt đóng sẵn, bấm tiêu đề để mở.',tags:['Giao diện']},{version:'1.18.2',title:'Họa tiết ghi chú dịu hơn',text:'Họa tiết trên thẻ ghi chú và khung soạn giờ chỉ là nét điểm nhẹ phía sau chữ, cả chế độ sáng và tối; chữ vẫn là nội dung chính.',tags:['Ghi chú','Giao diện']},{version:'1.18.1',title:'Nút đóng hộp thoại có chuyển động',text:'Nút × ở mọi hộp thoại giờ bật vào khi mở, xoay nhẹ khi rê chuột hoặc dùng bàn phím và co lại khi nhấn; tắt khi bạn chọn giảm chuyển động.',tags:['Giao diện']},{version:'1.18.0',title:'Sửa công việc ngay trong Chế độ tập trung',text:'Sửa tên, mô tả và checklist (tích, sửa chữ, thêm, xóa có hoàn tác, đổi thứ tự) ngay trong Chế độ tập trung mà không mở hộp thoại; mọi thay đổi tự lưu.',tags:['Công việc','Chế độ tập trung']},{version:'1.17.6',title:'Thẻ việc Chế độ tập trung có hiệu ứng khi lướt chuột',text:'Thẻ việc trong Chế độ tập trung nhấc nhẹ, hiện vạch nhấn màu dự án và nhích nút Tập trung khi lướt chuột hoặc dùng bàn phím; tắt khi chọn giảm chuyển động.',tags:['Chế độ tập trung','Giao diện']},{version:'1.17.5',title:'Nút Chế độ tập trung rõ ràng hơn',text:'Nút vào Chế độ tập trung trong hộp công việc nay có chữ, nằm trong một khu vực nền nhạt bo tròn, không còn chỉ là biểu tượng khó hiểu.',tags:['Chế độ tập trung']},{version:'1.17.4',title:'Checklist dễ xem và dễ sửa',text:'Mỗi mục checklist là một thẻ bo tròn, có nút lên/xuống để đổi thứ tự bằng chạm hoặc bàn phím, ô thêm mục gọn một dòng nhấn Enter để thêm, chữ dài không còn bị cắt.',tags:['Checklist']},{version:'1.17.3',title:'Bảng Tất cả công việc dễ lọc và dễ quét',text:'Thêm chip lọc nhanh có số lượng (Tất cả, Hôm nay, Quá hạn, Sắp đến hạn, Đang thực hiện) và làm bảng công việc dễ quét hơn: trạng thái thẳng hàng có chấm màu, hàng quá hạn tô nhẹ.',tags:['Công việc']},{version:'1.17.2',title:'Ghi chú ghim nhanh dễ nhìn hơn',text:'Khu Ghi chú ghim nhanh ở thanh bên có ô màu theo màu ghi chú, tên, dòng xem trước, nút bỏ ghim dạng biểu tượng và lối tắt Tất cả ghi chú.',tags:['Ghi chú','Ghim']},{version:'1.17.1',title:'Thông báo gọn và dễ quét hơn',text:'Hộp thoại Thông báo gom việc theo nhóm Quá hạn, Sắp đến hạn, Quan trọng với số lượng, mỗi việc một hàng gọn; thanh nhắc hạn và hộp Công việc cần chú ý có màu theo mức độ.',tags:['Thông báo']},{version:'1.17.0',title:'Nút chế độ sáng/tối cạnh chuông',text:'Thêm nút chuyển nhanh giao diện sáng/tối ngay cạnh biểu tượng thông báo trên thanh trên cùng, dùng được trên điện thoại, máy tính bảng và máy tính.',tags:['Chế độ tối','Giao diện']},{version:'1.16.6',title:'Gỡ chế độ xem Dòng thời gian',text:'Bỏ hoàn toàn chế độ xem Dòng thời gian khỏi menu, thanh chế độ xem trên điện thoại và hướng dẫn. Còn Bảng Kanban, Lịch và Gantt; dữ liệu ngày của công việc giữ nguyên.',tags:['Điều hướng']},{version:'1.16.5',title:'Lời chào hiện đủ 4 buổi trong ngày',text:'Sửa lỗi lời chào Chào mừng bạn trở lại không hiện lại ở các buổi sáng, trưa, chiều, tối sau khi đã bấm đã đọc một lần.',tags:['Lời chào']},{version:'1.16.4',title:'Xóa Thùng rác không cần mật khẩu',text:'Dọn sạch Thùng rác, xóa vĩnh viễn từng mục và xóa tệp đính kèm trong Thùng rác không còn đòi nhập lại mật khẩu, nên bấm Đồng bộ cũng không bị hỏi nữa; vẫn có hộp xác nhận và cảnh báo không thể hoàn tác. Chia sẻ vẫn cần mật khẩu.',tags:['Thùng rác']},{version:'1.16.3',title:'Xóa dự án đúng dự án',text:'Nút Xóa dự án này trong biểu mẫu dự án nay xóa đúng dự án đang được sửa, không còn dựa vào dự án đang mở phía sau. Cách mở biểu mẫu, hộp xác nhận và việc chuyển vào Thùng rác không đổi.',tags:['Dự án','Sửa lỗi']},{version:'1.16.2',title:'Chế độ tối hoàn thiện hơn',text:'Biểu đồ Gantt và vòng Bức tranh công việc đã có nền tối, nhãn ngày sáng rõ. Nút Làm mới ở Chế độ tập trung không còn bị trắng khi bật tương phản cao. Chỉ đổi giao diện tối và tương phản cao; dữ liệu và chế độ sáng không đổi.',tags:['Chế độ tối']},{version:'1.16.1',title:'Khởi động ổn định hơn',text:'Ứng dụng báo rõ khi đã khởi động xong, để màn hình đăng nhập và các thao tác ngay sau khi mở không bị xóa nhầm bởi bước tải dữ liệu còn đang chạy. Dữ liệu và giao diện không đổi.',tags:['Sửa lỗi']},{version:'1.16.0',title:'Chế độ tối và tương phản cao',text:'Giao diện có thêm chế độ tối và tương phản cao. Mặc định theo cài đặt của thiết bị; có thể chọn tay trong Cài đặt → Giao diện hoặc bằng Ctrl+K. Lựa chọn chỉ lưu trên thiết bị này, không ảnh hưởng dữ liệu.',tags:['Chế độ tối','Giao diện']},{version:'1.15.54',title:'Dọn mã giao diện (đợt 1)',text:'Gỡ 51 khai báo giao diện thừa đã bị ghi đè hoàn toàn và đặt ngân sách để số quy tắc ép buộc không tăng lại. Giao diện không đổi; đây là bước chuẩn bị cho chế độ tối.',tags:['Mã nguồn']},{version:'1.15.53',title:'Nút xóa việc và dự án tinh tế hơn',text:'Khu vực xóa việc và xóa dự án có biểu tượng thùng rác, tiêu đề và lời giải thích rõ (chuyển vào Thùng rác, khôi phục được trong 30 ngày), nút viền đỏ nhạt thay vì khối đỏ đặc. Cách xóa và xác nhận không đổi.',tags:['Công việc','Giao diện']},{version:'1.15.52',title:'Việc hoàn thành chìm xuống',text:'Thẻ việc ở cột Hoàn thành được rút màu, nền xám nhạt, tiêu đề gạch ngang và nhãn chuyển xám để mắt không phải chú ý tới nữa. Chữ vẫn rõ, đưa chuột hoặc chọn thẻ thì thẻ hiện lại đầy đủ.',tags:['Công việc','Giao diện']},{version:'1.15.51',title:'Ghim ghi chú rõ ràng hơn',text:'Khu vực ghim trong ghi chú có biểu tượng minh họa, tiêu đề và mô tả cho từng kiểu ghim (lên đầu danh sách, ghim nhanh ở menu). Ghim đang bật đổi màu nổi bật, nút to dễ bấm trên điện thoại. Cách ghim và bỏ ghim không đổi.',tags:['Ghim','Ghi chú']},{version:'1.15.50',title:'Bỏ họa tiết ở dự án và việc',text:'Dự án và việc không còn lựa chọn họa tiết, thẻ và trang không còn vẽ họa tiết nền nên dễ đọc hơn. Họa tiết bạn đã chọn trước đây vẫn được giữ trong dữ liệu, không bị xóa hay ghi đè khi lưu. Ghi chú vẫn có họa tiết như cũ.',tags:['Dự án','Giao diện']},{version:'1.15.49',title:'Lịch dạng danh sách cho màn hình vừa',text:'Ở máy tính bảng, trang Lịch hiện theo danh sách từng ngày dễ đọc thay cho lưới 7 cột chật; có nút đổi qua lại giữa Danh sách và Lưới tháng, và máy nhớ lựa chọn của bạn.',tags:['Lịch']},{version:'1.15.48',title:'Gantt dễ kéo bằng ngón tay',text:'Trên màn hình cảm ứng, đầu kéo và nút nối của biểu đồ Gantt có vùng chạm 44px nên kéo dời lịch hoặc nối phụ thuộc bằng ngón tay không còn trượt; trên chuột mọi thứ giữ nguyên.',tags:['Gantt']},{version:'1.15.47',title:'Hộp thoại còn lại dễ chạm hơn',text:'Sáu hộp thoại trước đây chưa được kiểm tra truy cập (báo cáo tuần, chia sẻ báo cáo, chọn ngày, lời chào, tải tệp, thanh lệnh) nay đã được quét; nút Tháng trước/Tháng sau của bảng chọn ngày và nút Đóng lời chào được nới lên 44px trên màn hình cảm ứng. Không đổi dữ liệu.',tags:['Giao diện']},{version:'1.15.46',title:'Một nơi báo sự cố đồng bộ',text:'Khi đồng bộ gặp sự cố (máy chủ từ chối, dữ liệu không hợp lệ, xung đột), thông báo nổi không còn nói lại điều viên thuốc và khung báo lỗi đã nói; khung có thêm một dòng trấn an rằng bản nháp vẫn ở thiết bị. Dòng tự lưu của ghi chú và vài thông báo còn lại dùng chung chữ trên thiết bị. Không đổi dữ liệu và cách đồng bộ.',tags:['Đồng bộ','Thông báo']},{version:'1.15.45',title:'Thẻ gọn và checklist khớp nhau',text:'Khi Thẻ gọn đang ẩn checklist trên thẻ, ô Hiện checklist trên thẻ trong menu Hiển thị nay bỏ dấu, bị khóa và ghi rõ lý do thay vì vẫn đánh dấu như đang hiện. Lựa chọn bạn đã lưu không bị đổi và trở lại khi tắt Thẻ gọn. Không đổi dữ liệu.',tags:['Checklist','Công việc']},{version:'1.15.44',title:'Một trạng thái lưu',text:'Trạng thái lưu và đồng bộ nay dùng một bộ chữ và một cách phân loại ở mọi nơi: viên thuốc ở thanh trên, khung báo lỗi bên dưới và dòng trạng thái trong hộp thoại chi tiết việc cùng nói một điều. Nhãn lỗi không còn lặp chữ Chưa đồng bộ; khi máy chủ lỗi mà vẫn có mạng thì ghi Chưa kết nối được thay vì Ngoại tuyến; viên thuốc dùng nhãn ngắn, khung lỗi nêu đầy đủ kèm nút Thử lại, không lặp một câu hai lần. Bỏ nhãn Báo cáo đồng bộ không bấm được ở chân thanh bên (báo cáo vẫn nằm trong Cài đặt). Không đổi dữ liệu và cách đồng bộ.',tags:['Đồng bộ']},{version:'1.15.43',title:'Một kênh nhắc việc',text:'Việc quá hạn và việc đến hạn trong 3 ngày nay nhắc chủ yếu ở một nơi là thanh nhắc đầu trang; số trên chuông bằng đúng số ở thanh đó (trước đây thanh nhắc, chuông và thông báo nổi mỗi nơi một số, và thông báo nổi lặp lại cùng tin mỗi giờ). Thông báo nổi chỉ hiện khi có việc mới đến hạn, không lặp lại. Phiên bản mới, tệp mới và nhắc ghi chú báo bằng một chấm nhỏ cạnh chuông, không cộng vào số. Hộp thoại Thông báo mở đầu bằng một dòng tóm tắt khớp với số trên chuông. Không đổi dữ liệu.',tags:['Thông báo']},{version:'1.15.42',title:'Danh sách việc gọn hơn',text:'Màn hình Tất cả công việc gọn hơn: mỗi việc một hàng thấp (khoảng 53px trên máy tính, 123px trên điện thoại thay vì 309px), tên dự án nằm ngay dưới tên việc, ngày và ưu tiên là chip bấm để sửa. Không còn nhãn Hạn chót lặp ở từng hàng; việc quá hạn ghi một lần, việc đã xong nằm cuối danh sách. Có dòng giải thích ô vuông dùng để chọn nhiều việc. Không đổi dữ liệu.',tags:['Công việc']},{version:'1.15.41',title:'Dễ chạm, dễ dùng bàn phím',text:'Hộp thoại thêm việc, dự án mới và ghi chú mới mở vào thẳng ô tên (trên điện thoại, việc đã có thì không bật bàn phím); mọi hộp thoại có tên để trình đọc màn hình đọc. Trên màn hình cảm ứng, nút, ô chọn và ô nhập chính cao tối thiểu 44px; ở mọi thiết bị mỗi điều khiển tối thiểu 24px. Chi tiết việc trên điện thoại: phím Tab đi đúng thứ tự nhìn. Sửa tiêu đề trùng chữ ở hộp thoại Cài đặt. Không đổi dữ liệu.',tags:['Điều hướng','Giao diện']},{version:'1.15.40',title:'Chữ dễ đọc hơn',text:'Chữ nhỏ nhất nay là 12px (trước có chỗ chỉ 8–11px); chữ phụ, nhãn, hạn và tab dùng màu đậm hơn để đạt tương phản tối thiểu 4,5:1; nút tím–hồng sẫm hơn để chữ trắng đọc rõ; viền ô nhập và chữ gợi ý rõ hơn. Thẻ Hoàn thành và tab dự án không chọn không còn bị làm mờ cả chữ. Không đổi dữ liệu.',tags:['Giao diện']},{version:'1.15.39',title:'Từ ngữ giao diện thống nhất',text:'Giao diện dùng một bộ từ tiếng Việt: Bảng Kanban, Dòng thời gian, Lịch, Cài đặt, việc (thay cho task), Hoàn thành (thay cho Done) và Giới hạn việc mỗi cột (thay cho WIP). Ô Cột trong biểu mẫu việc hiện tên cột đang dùng thay vì Idea, List, Doing, Done. Thanh chế độ xem trên điện thoại hiện đủ tên mới nên cao hơn vài điểm ảnh. Không đổi dữ liệu.',tags:['Giao diện']},{version:'1.15.38',title:'Thẻ gọn mặc định trên điện thoại',text:'Trên điện thoại, thẻ công việc mặc định ở chế độ gọn (ẩn mô tả, checklist và bước tiếp theo) để cột ngắn lại và ít phải cuộn; có thể chọn Thẻ gọn tắt trong menu Hiển thị và lựa chọn đó được giữ. Màn hình rộng vẫn mặc định thẻ đầy đủ. Không đổi dữ liệu.',tags:['Giao diện']},{version:'1.15.37',title:'Gom nút phụ vào menu Hiển thị',text:'Thẻ gọn, Giới hạn WIP và Lệnh nhanh nằm trong menu Hiển thị của dự án thay vì một hàng nút riêng dưới khối tiến độ, nên thẻ đầu tiên lên cao hơn. Các nút vẫn làm việc như cũ; Ctrl/⌘ K vẫn mở Lệnh nhanh. Không đổi dữ liệu.',tags:['Giao diện']},{version:'1.15.36',title:'Đầu trang dự án gọn hơn',text:'Đầu trang dự án chỉ còn một nút chính là Thêm việc; Ghim, Lưu trữ, Tệp và Sửa dự án nằm trong menu Tùy chọn. Khối tiến độ ghi rõ số việc đã xong (ví dụ 3/14 việc xong) cùng phần trăm. Trên điện thoại thẻ đầu tiên hiện ngay trong màn hình đầu. Không đổi dữ liệu.',tags:['Dự án','Giao diện']},{version:'1.15.35',title:'Thẻ Kanban gọn hơn',text:'Nút chuyển nhanh thu thành mũi tên cạnh hạn thay vì một hàng riêng ở mỗi thẻ; việc chưa có checklist không còn hiện 0% và thanh tiến độ trống; khoảng cách trong thẻ chặt hơn. Thẻ thấp hơn khoảng 43%. Không đổi dữ liệu.',tags:['Công việc','Giao diện']},{version:'1.15.34',title:'Khung điều hướng ổn định',text:'Từ màn hình 701px, thanh trên (ô tìm kiếm, trạng thái đồng bộ) và dải tab dự án luôn nằm ở đầu màn hình khi cuộn; chuyển màn hình thì về đầu trang. Đường dẫn của trang Lưu trữ và Thùng rác không còn trống. Không đổi dữ liệu.',tags:['Điều hướng']},{version:'1.15.33',title:'Sửa bố cục tablet',text:'Tên dự án và tiêu đề trang không còn bị bóp thành từng chữ ở màn hình 701–1000px; phần trăm tiến độ trên tab không còn bị bẻ dòng; thanh trên không còn tràn ngang. Không đổi dữ liệu.',tags:['Giao diện']},{version:'1.15.32',title:'Lịch gọn hơn cho task dài ngày',text:'Task nhiều ngày hiện thành một thanh liền xuyên các ngày trong tuần thay vì lặp một thẻ ở mỗi ngày. Không đổi dữ liệu.',tags:['Lịch']},{version:'1.15.31',title:'Sửa giao diện thẻ công việc',text:'Nút chuyển nhanh nằm gọn trong thẻ, không còn tràn ra ngoài; họa tiết phủ nhẹ lên nền thẻ thay cho ô vuông lệch. Không đổi dữ liệu.',tags:['Công việc','Giao diện']},{version:'1.15.30',title:'Tài liệu khớp thực tế',text:'Cập nhật tài liệu dự án cho đúng cách phát hành và triển khai. Không đổi tính năng, dữ liệu hay giao diện.',tags:['Tài liệu']},{version:'1.15.29',title:'Ghim nhanh ghi chú và task',text:'Tách Ghim ghi chú và Ghim nhanh; tối đa 3 ghi chú ghim nhanh trên thanh tab, mục Pin trong menu dành cho task. Họa tiết ghi chú phủ nhẹ từng thẻ và khung soạn.',tags:['Ghim','Ghi chú']},{version:'1.15.25',title:'Ghim nhanh ghi chú và task',text:'Thêm truy cập nhanh ghi chú và ghim task trong menu.',tags:['Ghim']},{version:'1.15.24',title:'Mobile calendar, checklist và dự án',text:'Cải thiện lịch mobile, checklist, họa tiết dự án và xác nhận khôi phục.',tags:['Lịch','Checklist']},{version:'1.14.7',title:'Gantt linh hoạt, báo cáo rõ ràng',text:'Tạo công việc trực tiếp từ ngày trên Gantt và sắp xếp nhanh các việc chưa có lịch. Căn chỉnh nút Focus gọn hơn; cải thiện cách trình bày phân bố trạng thái, tổng kết dự án và nhịp tuần trong báo cáo PDF.',tags:['Gantt','Báo cáo']},{version:'1.14.6',title:'Báo cáo rõ ràng, lịch gọn nhẹ',text:'Tối ưu bố cục in và lưu PDF; chia sẻ báo cáo mặc định công khai trong 1 ngày. Gõ 1. hoặc * rồi Space để tạo danh sách và tiếp tục bằng Enter. Lịch task dùng ngày bắt đầu/kết thúc, trong đó ngày kết thúc là hạn; nút Focus có chú thích và căn chỉnh gọn hơn.',tags:['Báo cáo','Lịch']},{version:'1.14.4',title:'Dự án rõ nhịp, tập trung dễ hơn',text:'Ngày và họa tiết dự án, Timeline gọn trong thẻ, truy cập tập trung nhanh, kiểm tra dữ liệu tự động và thủ công. Cải thiện nút Lưu, menu danh sách, liên kết ghi chú, bộ lọc và chi tiết báo cáo web.',tags:['Dự án']},{version:'1.14.3',title:'Lời chào nhẹ nhàng, thông báo đồng bộ',text:'Làm gọn lời chào; xác nhận đã đọc theo tài khoản trên mọi thiết bị. Thêm 30 lời khích lệ khi hoàn thành việc, sửa khung mô tả và Timeline, bổ sung họa tiết Nông trại, Gia đình, Tài chính cho ghi chú và công việc.',tags:['Thông báo','Đồng bộ']},{version:'1.14.2',title:'Khôi phục mốc đồng bộ',text:'Khôi phục phiên bản đồng bộ bị thiếu bằng hợp nhất an toàn. Phân biệt lỗi mốc phiên bản với nội dung, hiển thị phản hồi cụ thể từ máy chủ.',tags:['Đồng bộ']},{version:'1.13.2',title:'Giữ an toàn bản nháp',text:'Giữ bản nháp chưa đồng bộ khi mở lại tài khoản; báo rõ dung lượng hoặc dữ liệu chưa hợp lệ. Lịch sử ghi chú có thể xem khi bản nháp đang chờ; tinh gọn bộ lọc và giao diện tập trung.',tags:['Ghi chú']},{version:'1.13.1',title:'Gọn lựa chọn, rõ trạng thái',text:'Bộ lọc dạng nhãn màu bo tròn, Cài đặt chia nhóm, nút thêm checklist canh phải. Dọn Thùng rác chờ đồng bộ đang chạy và trả kết quả rõ ràng.',tags:['Giao diện']},{version:'1.13.0',title:'Một việc mỗi lúc',text:'Chế độ tập trung gom việc đến hạn, quá hạn và gợi ý ba ưu tiên. Ghi chú liên kết xuất hiện trong dự án, mô tả dự án có định dạng và lựa chọn liên kết được thu gọn.',tags:['Công việc']},{version:'1.12.1',title:'Gọn bộ lọc, rõ công việc',text:'Bộ lọc thu gọn, bình luận rộng hơn, liên kết từ ghi chú sang công việc/dự án. Ghi nhớ dự án gần nhất và nhấn mạnh tab đang xem; kết quả tìm kiếm có từ khóa nổi bật.',tags:['Công việc']},{version:'1.12.0',title:'Làm việc liền mạch hơn',text:'Giữ vị trí checklist khi sắp xếp; thêm mẫu công việc, bình luận, nhãn trạng thái và liên kết ghi chú. Đồng bộ rõ ràng trên mobile, lịch sử ghi chú dạng dòng thời gian và thao tác nhiều task.',tags:['Điều hướng']},{version:'1.11.2',title:'Củng cố logic, gọn mã nguồn',text:'Gom logic hiển thị trùng, dọn listener khi đóng form, thống nhất luồng tự lưu ghi chú. Kéo thả bỏ qua vị trí không hợp lệ và thao tác không thay đổi; kiểm tra tên cột ở trình duyệt và máy chủ.',tags:['Mã nguồn']},{version:'1.11.1',title:'Tinh chỉnh không gian làm việc',text:'Số ghi chú theo từ khóa, lịch sử 7 ngày gọn hơn, nút đồng bộ mobile, thông báo đã xem và đổi tên cột Kanban.',tags:['Giao diện']},{version:'1.11.0',title:'Giữ nhịp làm việc quen thuộc',text:'Chuyển và copy task giữa dự án, lưu trữ task, định dạng mô tả, thêm và sắp xếp checklist nhanh. Ghi chú tự lưu đầy đủ và kéo thả bằng tay nắm.',tags:['Giao diện']},{version:'1.10.2',title:'Ảnh ghi chú gọn gàng',text:'Sửa ảnh đính kèm còn sót sau khi gỡ để thẻ ghi chú giữ bố cục ổn định; tự ẩn ảnh tải lỗi.',tags:['Ghi chú']},{version:'1.10.1',title:'Tệp đính kèm gọn gàng',text:'Nhóm ảnh riêng khỏi tài liệu và các loại tệp khác; thu nhỏ ảnh xem trước theo khung, tên tệp dễ đọc và gỡ tệp ngay tại chỗ. Ảnh xem trước liên kết có hình dự phòng khi tệp ảnh không tải được. Đồng bộ số phiên bản 1.10.1 trên toàn ứng dụng.',tags:['Tệp đính kèm']},{version:'1.9.11',title:'Đồng bộ an tâm',text:'Sửa trạng thái đồng bộ kéo dài và cảnh báo sai, phân biệt lưu cục bộ/chờ mạng/dữ liệu bị từ chối; có giới hạn thời gian chờ và nút thử lại, không tự ghi đè bản khác.',tags:['Đồng bộ']},{version:'1.9.10',title:'Họa tiết an nhiên',text:'Nút ghim/bỏ ghim có hàng riêng, không đè lên tiêu đề ghi chú. Nâng cấp tám tranh nền thiên nhiên và thiền, thêm ảnh mẫu thu nhỏ để chọn trực quan, tương phản chữ rõ trên desktop/mobile.',tags:['Giao diện']},{version:'1.9.9',title:'Soạn thảo trực tiếp',text:'Định dạng ngay trong vùng nhập ghi chú; cải thiện tìm kiếm theo nhóm và sửa trạng thái, cơ chế đồng bộ dữ liệu tự động.',tags:['Ghi chú']},{version:'1.9.8',title:'Ghi chú sinh động',text:'Ghim ghi chú như Keep, tìm tệp và nội dung toàn dự án, họa tiết minh họa toàn thẻ, thanh định dạng văn bản, thumbnail và sửa nút đóng.',tags:['Ghi chú']},{version:'1.9.7',title:'Checklist nở hoa',text:'Checklist ghi chú có nút Thêm mục lưu tự động, thanh tiến độ trực quan và tám họa tiết thiên nhiên, thiền, yoga, tỉnh thức trên từng thẻ.',tags:['Checklist']},{version:'1.9.6',title:'Tìm kiếm ghi chú mở rộng',text:'Mở kết quả ghi chú từ thanh tìm kiếm chung và tối ưu giao diện nhập liệu trên điện thoại.',tags:['Tìm kiếm','Ghi chú']},{version:'1.9.5',title:'Ghi chú & Tài nguyên',text:'Gom ba tùy chọn ghi chú trên desktop, thu gọn thanh tab dự án và tải tệp ngay trong Tài nguyên.',tags:['Ghi chú','Tài nguyên']},{version:'1.9.4',title:'Giao diện linh hoạt',text:'Cải thiện hộp thoại, nút đóng và tab dự án trên nhiều kích thước màn hình.',tags:['Giao diện']},{version:'1.9.3',title:'Ghi chú gọn, sáng rõ',text:'Tối ưu nhập ghi chú trên Mobile: khung soạn vừa màn hình, giảm chiều cao các trường, nhóm tùy chọn phụ, sửa vị trí hiển thị và dễ lưu khi chạm.',tags:['Ghi chú']},{version:'1.9.2',title:'Học sâu, trở về mình',text:'Bổ sung 261 trích đoạn có nguồn: Mạnh Tử, Nam Hoa Kinh, Tuân Tử và các nguồn chính thức. Lưu nguyên bản, vị trí chương và bản tiếng Việt; phân biệt lời nhân vật trong tác phẩm với phát ngôn lịch sử.',tags:['Lời chào']},{version:'1.9.1',title:'Lời có nguồn, ngày có nhịp',text:'Bổ sung 185 trích đoạn có nguồn và bản tiếng Việt; toàn bộ trích đoạn tham gia vòng chọn, không lặp trong một chu kỳ. Lời biên soạn được giữ riêng và không tính vào mục tiêu 3.333.',tags:['Lời chào']},{version:'1.9.0',title:'Bốn mùa trong ngày',text:'Lời chào theo bốn buổi giờ Việt Nam, hồ sơ tư tưởng, nguồn tham khảo và chân dung tư liệu của các vị thầy.',tags:['Lời chào']},{version:'1.8.4',title:'Task cuộn liền mạch',text:'Thanh đầu của cửa sổ task cuộn cùng nội dung, giúp tập trung đọc và chỉnh sửa.',tags:['Công việc']},{version:'1.8.3',title:'Chữ rõ, việc nhẹ',text:'Tinh chỉnh font nhãn dự án và nội dung task để dễ đọc trên desktop, tablet và điện thoại.',tags:['Giao diện']},{version:'1.8.2',title:'Nhịp việc rõ ràng',text:'Thông báo đến hạn cuộn theo trang; báo cáo có khoảng lề rõ ràng; nhãn dự án theo màu; lưu task và đóng form, bấm thanh Gantt để sửa trực tiếp.',tags:['Công việc']},{version:'1.8.1',title:'Thanh âm ngày mới',text:'Nhạc nền Bamboo at Daybreak có nút phát, tạm dừng, âm lượng và màu tương phản theo nền. Phiên bản tự cập nhật trên màn hình đăng nhập.',tags:['Thông báo']},{version:'1.8.0',title:'Chia sẻ điều đang lớn',text:'Chia sẻ báo cáo qua web công khai hoặc có mật khẩu, chọn hạn 1–30 ngày và thu hồi. Mở rộng thư viện icon theo nhóm, tìm tiếng Anh; ghi chú có bánh xe màu HEX/RGB.',tags:['Chia sẻ']},{version:'1.7.0',title:'Dòng việc liền mạch',text:'Kéo đổi lịch Gantt trực tiếp, checklist ngay trên thẻ, ghi chú có từ khóa và email nhắc hạn, Thùng rác theo lưới/danh sách cùng thống kê và xóa có xác nhận.',tags:['Điều hướng']},{version:'1.6.3',title:'Chạm để hiểu',text:'Các ô thống kê mở danh sách và tiến độ chi tiết, hiệu ứng chuyển động nhẹ, thanh nhắc hạn dễ thao tác và ảnh hồ sơ hiển thị tại avatar.',tags:['Điều hướng']},{version:'1.6.2',title:'Nhịp an nhiên',text:'Form ghi chú và công việc rõ ràng, Mức độ bốn màu, font mềm mại, biểu đồ tròn trong PDF và phiên làm việc tự khóa sau 10 phút không thao tác.',tags:['Lời chào']},{version:'1.6.1',title:'Thông báo mở đúng chi tiết',text:'Nút Xem chi tiết mở phiên bản hoặc công việc liên quan, đồng bộ icon Dashboard mềm mại và thu gọn phiên bản cuối trang.',tags:['Thông báo']},{version:'1.6.0',title:'Gantt, ghi chú và tài nguyên',text:'Gantt có liên kết phụ thuộc và chặn vòng lặp; mở trực tiếp ghi chú, khung soạn bo tròn, tìm icon tiếng Anh và đổi tên tài nguyên.',tags:['Gantt','Ghi chú','Tài nguyên']},{version:'1.5.0',title:'Điều hướng & không gian làm việc tinh tế',text:'Kéo sắp xếp tab, tiến độ dự án đa chế độ, từ khóa dự án, lịch chọn ngày giờ, xác nhận lưu trữ và danh sách việc cần chú ý.',tags:['Điều hướng']},{version:'1.4.1',title:'Checklist gọn & thư viện tài nguyên',text:'Checklist một dòng, tổng kết email có biểu đồ % và tiến độ từng dự án, xem trước/In/Lưu PDF, album Tài nguyên riêng tư quản lý tệp.',tags:['Checklist','Tài nguyên']},{version:'1.4.0',title:'Bức tranh công việc & tổng kết tuần',text:'Biểu đồ tương tác bốn màu, nhắc hạn trước 3 ngày, email tổng kết Chủ nhật trong Settings, bảng icon và bánh xe HEX/RGB. Lưu trữ dự án đang làm dở.',tags:['Báo cáo']},{version:'1.3.8',title:'Lời chào mỗi ngày tinh gọn hơn',text:'Lược bỏ phần hiển thị bản dịch và bản tiếng Anh, cải thiện kiểu chữ, căn dòng và nút đóng.',tags:['Lời chào']},{version:'1.3.7',title:'Ma trận ưu tiên bốn màu',text:'Cập nhật bốn nhãn theo mức độ quan trọng và khẩn cấp: tím, xanh lá, hồng và cam.',tags:['Công việc']},{version:'1.3.6',title:'Toàn cảnh & công việc trong một màn hình',text:'Thống kê quá hạn, tổng quan đầu trang mobile, chỉnh task trực tiếp, ma trận bốn màu, tùy chọn Kanban và tiến độ Timeline/Calendar. Hướng dẫn đầy đủ.',tags:['Giao diện','Công việc']},{version:'1.3.4',title:'Thông báo đã xem & chuyển bước công việc',text:'Nút Đã xem tất cả đưa bộ đếm về bình thường. Chuyển task sang cột kế tiếp ngay trên thẻ.',tags:['Thông báo','Công việc']},{version:'1.3.3',title:'Ghi chú trực tiếp & lời chào mỗi ngày',text:'Viết ghi chú, thêm liên kết và tải tệp trong cùng khung. Lời chào hằng ngày có họa tiết thiên nhiên.',tags:['Ghi chú','Lời chào']}];
let latestVersion=APP_VERSION;
function localRead(k){try{return localStorage.getItem(k);}catch{return null;}}
function localWrite(k,v){try{localStorage.setItem(k,v);}catch{}}
// Read receipts belong to the signed-in account, independently of workspace revisions.
let readReceiptOwner=null,readReceiptKeys=new Set(),readReceiptLoaded=false,readReceiptRequest=null,readReceiptTime=0;
function noticeReceipt(t){return 'notice:'+encodeURIComponent(noticeSignature(t));}
async function loadReadReceipts(force=false){
 const owner=currentUser?.id;if(!owner)return false;
 if(readReceiptOwner!==owner){readReceiptOwner=owner;readReceiptKeys=new Set();readReceiptLoaded=false;readReceiptRequest=null;readReceiptTime=0;}
 if(readReceiptRequest)return readReceiptRequest;
 if(readReceiptLoaded&&!force&&Date.now()-readReceiptTime<10000)return true;
 const pending=(async()=>{try{const result=await requestAPI('notification-receipts');if(currentUser?.id!==owner||readReceiptOwner!==owner)return false;if(!Array.isArray(result.keys))throw Error('Invalid receipts');readReceiptKeys=new Set(result.keys.filter(k=>typeof k==='string'));readReceiptLoaded=true;readReceiptTime=Date.now();refreshBell();if(readReceiptKeys.has(welcomeReceipt(welcomeSlot())))document.querySelector('.welcome-dialog:not([data-manual])')?.close();return true;}catch{return false;}})();
 readReceiptRequest=pending;try{return await pending;}finally{if(readReceiptRequest===pending)readReceiptRequest=null;}
}
async function saveReadReceipts(keys){
 const owner=currentUser?.id;if(!owner)throw Error('Vui lòng đăng nhập.');
 for(let i=0;i<keys.length;i+=200)await requestAPI('notification-receipts','PUT',{keys:keys.slice(i,i+200)});
 if(currentUser?.id!==owner)throw Error('Tài khoản đã thay đổi.');
 if(readReceiptOwner!==owner){readReceiptOwner=owner;readReceiptKeys=new Set();readReceiptLoaded=false;}
 keys.forEach(key=>readReceiptKeys.add(key));refreshBell();
}
function releaseKey(){return 'zen-release-seen:'+currentUser?.id;}
function releaseUnread(){return !!currentUser&&!(readReceiptOwner===currentUser.id&&readReceiptKeys.has('release:'+latestVersion))&&localRead(releaseKey())!==latestVersion;}
const oldBellRefresh=refreshBell;refreshBell=function(){oldBellRefresh();if(releaseUnread()){const count=taskNotices().length+fileAlerts.length+1;bell.innerHTML=svgIcon('bell')+'<span class="notification-count">'+(count>99?'99+':count)+'</span>';bell.setAttribute('aria-label','Thông báo · '+count+' mục, có phiên bản mới');}};
const oldBellClick=bell.onclick;bell.onclick=()=>{oldBellClick();const list=$('#editor-body .notice-list');if(!releaseUnread())return;list.insertAdjacentHTML('afterbegin',`<article class="notice-item release-notice"><strong>${releaseUnread()?'Mới · ':''}Phiên bản ${esc(latestVersion)}</strong><span>${latestVersion===APP_VERSION?esc(RELEASES[0].text):'Có bản cập nhật mới. Tải lại trang để nhận tính năng mới nhất.'}</span><div class="release-actions"><button class="btn" type="button" id="release-read">${svgIcon('notes')}Xem chi tiết</button>${latestVersion!==APP_VERSION?'<button class="btn" id="release-reload" type="button">Tải lại trang</button>':''}</div></article>`);$('#release-read').onclick=async e=>{e.currentTarget.disabled=true;try{await saveReadReceipts(['release:'+latestVersion]);localWrite(releaseKey(),latestVersion);refreshBell();$('#editor').close();go('versions');}catch{notify('Chưa lưu được trạng thái đã đọc. Hãy thử lại.');e.target.closest('button').disabled=false;}};if($('#release-reload'))$('#release-reload').onclick=()=>location.reload();};
const releaseBullets=r=>Array.isArray(r.items)&&r.items.length?r.items:String(r.text||'').split(/(?<=[.!?])\s+/).filter(Boolean);
versions=()=>heading('NHẬT KÝ PHÁT TRIỂN','Phiên bản '+APP_VERSION,'Mỗi phiên bản một khung, kèm từ khóa hạng mục đã cải thiện')+'<section class="release-log" aria-label="Nhật ký phiên bản">'+RELEASES.map(r=>`<article class="release-card"><header><span class="release-ver">v${esc(r.version)}</span><h4>${esc(r.title)}</h4></header>${(r.tags||[]).length?`<div class="release-tags" aria-label="Từ khóa">${r.tags.map(t=>`<span class="release-tag">${esc(t)}</span>`).join('')}</div>`:''}<ul>${releaseBullets(r).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></article>`).join('')+'</section>';
async function checkRelease(){if(!currentUser||document.hidden||!navigator.onLine)return;try{const r=await fetch('/health',{cache:'no-store'});if(r.ok){const body=await r.json();if(/^\d+\.\d+\.\d+$/.test(body.version)){latestVersion=body.version;refreshBell();}}}catch{}}
let wisdomCache=null,teacherCache=null,welcomeLoading=false,welcomeSession=new Set();
function welcomeDay(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function wisdomIndex(day,count){return Math.floor((Date.parse(day+'T00:00:00Z')-Date.parse('2026-10-24T00:00:00Z'))/86400000+count*1000)%count;}
// v1.16.5: dấu "đã đọc" của lời chào riêng cho từng buổi (ngày + buổi 0-3); trước đây chỉ một dấu 'welcome' vĩnh viễn nên bấm đọc một lần là các buổi sau không bao giờ hiện lại.
function welcomeReceipt(time){return 'welcome:'+time.day+':'+time.slot;}
function welcomeSlot(now=new Date()){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',hourCycle:'h23'}).formatToParts(now),v=Object.fromEntries(parts.map(p=>[p.type,p.value])),hour=Number(v.hour),slot=hour<5?3:hour<11?0:hour<14?1:hour<18?2:3,calendarDay=v.year+'-'+v.month+'-'+v.day,day=hour<5?new Date(Date.parse(calendarDay+'T00:00:00Z')-86400000).toISOString().slice(0,10):calendarDay;return {day,slot,label:['Buổi sáng','Buổi trưa','Buổi chiều','Buổi tối'][slot],serial:Math.floor(Date.parse(day+'T00:00:00Z')/86400000)*4+slot};}
// Pure selection functions are embedded into welcome.js at build-authoring time.
// Every excerpt occurs exactly once in a complete cycle, including authors
// without a profile. Entries for each author are spread across the cycle.
function welcomeAllowed(entry) {
  return !/marcus\s+aurelius|stoic|khắc\s*kỷ|khac\s*ky|epictetus|seneca/i.test([entry.author,entry.name,entry.id,entry.school,entry.theme,entry.source].filter(Boolean).join(' '));
}
function welcomeProfile(author, profiles) {
  return profiles.filter(p => welcomeAllowed(p) && (author === p.name || author.startsWith(p.name + ' ·')))
    .sort((a,b) => b.name.length - a.name.length)[0];
}
function welcomeHash(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}
function welcomeDeck(quotes, profiles) {
  const groups = new Map();
  for (const quote of quotes) {
    if (!welcomeAllowed(quote) || typeof quote.vi !== 'string' || !quote.vi.trim()) continue;
    const profile = welcomeProfile(quote.author, profiles);
    const key = profile?.id || quote.author;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push({quote,profile});
  }
  const deck = [];
  for (const [key, entries] of groups) {
    entries.sort((a,b) => welcomeHash(a.quote.id || a.quote.vi) - welcomeHash(b.quote.id || b.quote.vi)
      || a.quote.vi.localeCompare(b.quote.vi));
    entries.forEach((entry,i) => deck.push({...entry, position:(i+0.5)/entries.length,key}));
  }
  return deck.sort((a,b) => a.position - b.position || a.key.localeCompare(b.key));
}
let welcomeDeckCache=null,welcomeDeckQuotes=null,welcomeDeckProfiles=null;
function welcomeSelection(time) {
  const profiles=teacherCache?.profiles||[];
  if(welcomeDeckQuotes!==wisdomCache||welcomeDeckProfiles!==profiles){
    welcomeDeckCache=welcomeDeck(wisdomCache,profiles);
    welcomeDeckQuotes=wisdomCache;welcomeDeckProfiles=profiles;
  }
  if(!welcomeDeckCache.length)return {};
  const epoch=Math.floor(Date.parse('2026-10-24T00:00:00Z')/86400000)*4;
  const index=((time.serial-epoch)%welcomeDeckCache.length+welcomeDeckCache.length)%welcomeDeckCache.length;
  return welcomeDeckCache[index];
}

// v1.19.1: tải kho câu có giới hạn thời gian (trước đây một yêu cầu treo làm lời chào kẹt mãi) và thử lại sau 5/10/15 giây khi lỗi mạng.
async function welcomeFetchJson(url,ms=8000){const c=new AbortController(),t=setTimeout(()=>c.abort(),ms);try{const r=await fetch(url,{signal:c.signal});if(!r.ok)throw Error(url);return await r.json();}finally{clearTimeout(t);}}
const welcomeRetries=new Map();
function welcomeRetryLater(key){const n=(welcomeRetries.get(key)||0)+1;welcomeRetries.set(key,n);if(n<=3)setTimeout(dailyWelcome,5000*n);}
// Mốc đổi buổi theo giờ Việt Nam (UTC+7, không có giờ mùa hè): 05:00, 11:00, 14:00, 18:00. Trả về số mili giây tới mốc kế tiếp.
function welcomeNextBoundary(now=Date.now()){const day=86400000,t=(((now+7*3600000)%day)+day)%day,marks=[5,11,14,18].map(h=>h*3600000),next=marks.find(m=>m>t);return (next===undefined?marks[0]+day:next)-t;}
function scheduleWelcomeBoundary(){setTimeout(()=>{dailyWelcome();scheduleWelcomeBoundary();},welcomeNextBoundary()+1500);}
async function dailyWelcome(force=false){
 if(!currentUser||document.hidden||welcomeLoading||$('#editor').open||document.querySelector('.welcome-dialog'))return;
 const owner=currentUser.id,time=welcomeSlot(),key='zen-welcome:'+owner+':'+time.day+':'+time.slot;
 if(!force&&(localRead(key)||welcomeSession.has(key)))return;
 welcomeLoading=true;
 try{
  // v1.19.1: dấu đã đọc của máy chủ chỉ để không hiện trùng giữa các thiết bị. Máy chủ chậm hoặc lỗi thì vẫn chào (dấu trên máy này chặn lặp lại), không để lời chào im lặng.
  await Promise.race([loadReadReceipts(),new Promise(r=>setTimeout(r,6000))]);
  if(!force&&readReceiptOwner===owner&&readReceiptKeys.has(welcomeReceipt(time)))return;
  if(!wisdomCache)wisdomCache=(await welcomeFetchJson('/wisdom.json')).filter(q=>typeof q.vi==='string'&&q.vi.trim());
  if(!teacherCache){try{teacherCache=await welcomeFetchJson('/teachers.json');}catch{}}
  if(currentUser?.id!==owner||$('#editor').open)return;
  const {quote:q,profile}=welcomeSelection(time);if(!q)return;
  const d=document.createElement('dialog');d.className='welcome-dialog';if(force)d.dataset.manual='true';d.setAttribute('aria-labelledby','welcome-title');
  d.innerHTML=`<button type="button" class="welcome-close" aria-label="Đóng lời chào" title="Đóng">×</button><div class="welcome-content"><header class="welcome-heading"><span class="welcome-lotus" aria-hidden="true">❀</span><p class="eyebrow">${esc(time.label)} · MỘT KHOẢNH KHẮC CHO BẠN</p><h2 id="welcome-title">Chào mừng bạn trở lại</h2><p class="welcome-intro">Dừng một nhịp, rồi bắt đầu điều có ý nghĩa.</p></header><blockquote lang="vi">${esc(q.vi)}</blockquote><div class="wisdom-teacher">${profile?.image?'<img src="'+esc(profile.image)+'" alt="'+esc(profile.imageAlt||profile.name)+'" width="48" height="48">':''}<span><strong>${esc(profile?.name||q.author)}</strong><small>${esc(profile?.theme||q.attribution||'Một điều để chiêm nghiệm')}</small></span></div><details class="welcome-sources"><summary>Nguồn & thông tin trích dẫn</summary><p class="wisdom-kind">${esc(q.translationNote||'Bản dịch tiếng Việt · tham khảo')}</p><p class="wisdom-author">${esc(q.attribution||q.author)}</p><a href="${esc(q.url)}" target="_blank" rel="noopener noreferrer">${esc(q.source)} ↗</a>${q.contextUrl?'<a href="'+esc(q.contextUrl)+'" target="_blank" rel="noopener noreferrer">Giải nghĩa trích đoạn ↗</a>':''}${profile?.imageSource?'<a href="'+esc(profile.imageSource)+'" target="_blank" rel="noopener noreferrer">Nguồn ảnh chân dung ↗</a>':''}<details class="wisdom-directory"><summary>Thư viện · ${wisdomCache.filter(q=>q.kind!=='reflection').length} trích đoạn có nguồn</summary><p>Bản dịch nghĩa mang tính tham khảo. Lời biên soạn của Zen Studio được ghi riêng, không phải phát ngôn của vị thầy.</p>${(teacherCache?.profiles||[]).filter(welcomeAllowed).map(p=>'<a href="'+esc(p.url)+'" target="_blank" rel="noopener noreferrer">'+esc(p.name)+' · '+esc(p.theme)+'</a>').join('')}</details></details><footer class="welcome-actions"><button type="button" class="btn primary" id="welcome-read">${svgIcon('check')}Đã đọc · Bắt đầu làm việc</button><small>Không tự hiện lại trên các thiết bị của bạn. Có thể mở lại từ Thông báo.</small><p id="welcome-read-status" role="status" hidden></p></footer></div>`;
  document.body.append(d);d.addEventListener('close',()=>d.remove());d.querySelector('.welcome-close').onclick=()=>d.close();
  const portrait=d.querySelector('.wisdom-teacher img');portrait?.addEventListener('error',()=>portrait.remove(),{once:true});
  d.querySelector('#welcome-read').onclick=async e=>{const button=e.currentTarget,status=d.querySelector('#welcome-read-status');button.disabled=true;try{await saveReadReceipts([welcomeReceipt(time)]);d.close();}catch{status.hidden=false;status.textContent='Chưa lưu được xác nhận. Kiểm tra kết nối rồi thử lại.';button.disabled=false;}};
  d.showModal();d.scrollTop=0;welcomeSession.add(key);localWrite(key,'seen');
 }catch{welcomeRetryLater(key);}finally{welcomeLoading=false;}
}
const beforeWelcomeRender=render;render=function(){beforeWelcomeRender();if(currentUser)loadReadReceipts();setTimeout(dailyWelcome,700);};
setInterval(checkRelease,300000);setInterval(dailyWelcome,60000);window.addEventListener('focus',()=>{checkRelease();dailyWelcome();});setTimeout(dailyWelcome,1000);refreshBell();
// v1.19.1: chào ngay khi tab hiện lại, khi có mạng lại, khi quay lại từ bộ nhớ đệm trang, và đúng lúc sang buổi mới (không đợi nhịp 60 giây).
document.addEventListener('visibilitychange',()=>{if(!document.hidden){checkRelease();dailyWelcome();}});window.addEventListener('online',()=>dailyWelcome());window.addEventListener('pageshow',e=>{if(e.persisted)dailyWelcome();});scheduleWelcomeBoundary();
function noticeSignature(t){return [t.id,t.notice,t.due||'',t.title,t.important].join('|');}
function seenNotices(){let local=[];try{local=JSON.parse(localRead('zen-notices:'+currentUser?.id)||'[]');}catch{}return [...new Set([...local,...[...(readReceiptOwner===currentUser?.id?readReceiptKeys:[])].filter(k=>k.startsWith('notice:')).map(k=>{try{return decodeURIComponent(k.slice(7));}catch{return '';}})])];}
async function markNoticesRead(){await saveReadReceipts(['release:'+latestVersion,...taskNotices().map(noticeReceipt)]);localWrite('zen-notices:'+currentUser?.id,JSON.stringify(taskNotices().map(noticeSignature)));fileAlerts=[];localWrite(releaseKey(),latestVersion);refreshBell();}
refreshBell=function(){const seen=new Set(seenNotices()),count=taskNotices().filter(t=>!seen.has(noticeSignature(t))).length+fileAlerts.length+(releaseUnread()?1:0);bell.innerHTML=svgIcon('bell')+(count?'<span class="notification-count">'+(count>99?'99+':count)+'</span>':'');bell.setAttribute('aria-label','Thông báo · '+count+' chưa xem');};
const beforeReadBell=bell.onclick;bell.onclick=()=>{beforeReadBell();const b=$('#clear-file-alerts');b.textContent='Xác nhận đã đọc tất cả';const tools=document.createElement('div');tools.className='notice-read-toolbar';$('#editor-body .notice-list').before(tools);tools.append(b);b.onclick=async()=>{b.disabled=true;try{await markNoticesRead();$('#editor').close();}catch{b.disabled=false;notify('Chưa lưu được xác nhận. Kiểm tra kết nối rồi thử lại.');}};const open=document.createElement('button');open.type='button';open.className='btn welcome-reopen';open.textContent='❀ Một điều để chiêm nghiệm';open.onclick=()=>{$('#editor').close();dailyWelcome(true);};$('#editor-body').append(open);const seen=new Set(seenNotices());document.querySelectorAll('.notice-list [data-task]').forEach(el=>{const t=taskNotices().find(t=>t.id===el.dataset.task&&t.project.id===el.dataset.pid);if(t&&seen.has(noticeSignature(t)))el.closest('.notice-item')?.remove();});};
const beforeNextCard=taskCard;taskCard=function(t,p){const html=beforeNextCard(t,p),next=p.columns[p.columns.indexOf(t.col)+1];return next?html.replace('</article>',`<button type="button" class="btn task-next" data-next-task="${esc(t.id)}" data-next-project="${esc(p.id)}">${svgIcon('check')}Chuyển sang ${esc(next)} →</button></article>`):html;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-next-task]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const p=project(b.dataset.nextProject),t=p?.tasks.find(t=>t.id===b.dataset.nextTask);if(!t)return;const next=p.columns[p.columns.indexOf(t.col)+1];if(!next)return;t.col=next;if(next==='Done'){t.checks.forEach(c=>c.done=true);celebrateCompletion(completionKindFor(p,t));}save();render();},true);
refreshBell();

